//! Built-in RaTeX math layout. No host callback, browser or external font file is needed.

use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::rc::Rc;

use ratex_layout::{layout, to_display_list, validate_layout, LayoutOptions};
use ratex_svg::{render_to_svg_with_color_syntax, SvgColorSyntax, SvgOptions};
use ratex_types::{color::Color, display_item::DisplayItem};

/// Self-contained SVG glyph outlines and their dimensions in pixels, generated by RaTeX.
#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
pub struct MathMarkup {
    pub svg: String,
    pub width: f64,
    pub height: f64,
    #[cfg_attr(feature = "serde", serde(skip))]
    pub(crate) native_foreground: Option<[u8; 7]>,
}

impl MathMarkup {
    pub fn width(&self) -> f64 {
        self.width
    }
    pub fn height(&self) -> f64 {
        self.height
    }
}

/// The cache belongs to one diagram render, including its width-fitting retries. A diagram
/// without math creates no cache entries and never initializes RaTeX's fonts.
pub(crate) struct Math {
    allow_images: bool,
    native_foreground: Option<[u8; 7]>,
    found: RefCell<HashMap<String, Option<Rc<MathMarkup>>>>,
}

impl Default for Math {
    fn default() -> Self {
        Self { allow_images: true, native_foreground: None, found: RefCell::new(HashMap::new()) }
    }
}
impl Math {
    pub fn with_images(mut self, allow: bool) -> Self {
        self.allow_images = allow;
        self
    }
    pub fn native(foreground: &str) -> Self {
        Self { native_foreground: foreground.as_bytes().try_into().ok(), ..Self::default() }
    }
    pub fn typeset(&self, tex: &str, size: f64) -> Option<Rc<MathMarkup>> {
        let key = format!("{}\n{tex}", crate::util::js::number_text(size));
        if let Some(found) = self.found.borrow().get(&key) {
            return found.clone();
        }
        let markup = typeset(tex, size).filter(|m| self.allow_images || !m.svg.contains("<image")).map(|mut m| {
            m.native_foreground = self.native_foreground;
            Rc::new(m)
        });
        self.found.borrow_mut().insert(key, markup.clone());
        markup
    }
}

fn color(item: &mut DisplayItem) -> &mut Color {
    match item {
        DisplayItem::GlyphPath { color, .. }
        | DisplayItem::Line { color, .. }
        | DisplayItem::Rect { color, .. }
        | DisplayItem::Path { color, .. } => color,
    }
}

fn rgb(c: &Color) -> u32 {
    let channel = |x: f32| (x.clamp(0.0, 1.0) * 255.0).round() as u32;
    channel(c.r) << 16 | channel(c.g) << 8 | channel(c.b)
}

pub(crate) fn typeset(tex: &str, size: f64) -> Option<MathMarkup> {
    if !size.is_finite() || size <= 0.0 {
        return None;
    }
    let ast = ratex_parser::parse(tex).ok()?;
    // RaTeX has numeric colors; an unrepresentable TeX color marks inherited foreground.
    // Before serialization replace it with an RGB value absent from all explicit colors.
    // This keeps explicit \\color{black} black while the default follows the host theme.
    let inherited = Color::new(f32::NAN, f32::NAN, f32::NAN, 1.0);
    let boxes = layout(&ast, &LayoutOptions::default().with_color(inherited));
    validate_layout(&boxes).ok()?;
    let mut list = to_display_list(&boxes);
    let width = list.width * size;
    let height = (list.height + list.depth) * size;
    if !width.is_finite() || width <= 0.0 || !height.is_finite() || height <= 0.0 {
        return None;
    }
    let mut used = HashSet::new();
    for item in &mut list.items {
        let c = color(item);
        if !c.r.is_nan() {
            used.insert(rgb(c));
        }
    }
    // validate_layout caps items below the 24-bit RGB space, so a free color always exists.
    let marker = (0..=0xffffff).find(|c| !used.contains(c))?;
    let (r, g, b) = ((marker >> 16) & 255, (marker >> 8) & 255, marker & 255);
    for item in &mut list.items {
        let c = color(item);
        if c.r.is_nan() {
            *c = Color::rgb(r as f32 / 255.0, g as f32 / 255.0, b as f32 / 255.0);
        }
    }
    let opts = SvgOptions { font_size: size, padding: 0.0, embed_glyphs: true, ..SvgOptions::default() };
    let svg = render_to_svg_with_color_syntax(&list, &opts, SvgColorSyntax::Rgb);
    // The label builder supplies the SVG viewport in pixels. Retaining RaTeX's outer SVG
    // would interpret its pt dimensions at 4/3 scale inside that viewport.
    let body = svg.get(svg.find('>')? + 1..svg.rfind("</svg>")?)?;
    let paint = format!("=\"rgb({r},{g},{b})\"");
    let svg = body.replace(&paint, "=\"currentColor\"");
    // Unsupported glyphs must fall back to source text rather than silently requiring a
    // KaTeX stylesheet. Ordinary math uses only the embedded KaTeX font outlines.
    if svg.contains("<text") {
        return None;
    }
    Some(MathMarkup { svg, width, height, native_foreground: None })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_outlines_scale_and_preserve_explicit_colors() {
        let small = typeset(r"x+\frac{1}{2}+\sqrt{y}", 16.0).unwrap();
        let large = typeset(r"x+\frac{1}{2}+\sqrt{y}", 32.0).unwrap();
        assert_eq!(large.width, small.width * 2.0);
        assert_eq!(large.height, small.height * 2.0);
        assert!(small.svg.contains("<path"));
        assert!(small.svg.contains("currentColor"));
        assert!(!small.svg.contains("<text"));
        let colored = typeset(r"x+\color{black}{y}+\color{red}{z}", 16.0).unwrap();
        assert!(colored.svg.contains("currentColor"));
        assert!(colored.svg.contains("rgb(0,0,0)"));
        assert!(colored.svg.contains("rgb(255,0,0)"));
    }

    #[test]
    fn invalid_math_falls_back_and_cache_is_scoped() {
        let first = Math::default();
        let a = first.typeset("x^2", 16.0).unwrap();
        assert!(Rc::ptr_eq(&a, &first.typeset("x^2", 16.0).unwrap()));
        assert!(!Rc::ptr_eq(&a, &Math::default().typeset("x^2", 16.0).unwrap()));
        assert!(first.typeset(r"\notACommand", 16.0).is_none());
        assert!(first.typeset(r"\notACommand", 16.0).is_none());
        assert!(first.typeset("x", f64::NAN).is_none());
    }
}
